Customer Portal App.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Customer Portal App container

Container_Boundary(customer_portal_app, "Customer Portal App") {
    Component(Claim_Submission_UI, "Claim Submission UI", "React, TypeScript", "User interface for customers and brokers to submit and view claims online.")
    Component(Authentication_Client, "Authentication Client", "OIDC / OAuth2, Azure Entra ID Connect", "Handles user authentication and single sign-on securely.")
}

System_Ext(Claims_Core_API, "Claims Core API", "Claims Core API (.NET Core modular monolith)")

Rel(Claim_Submission_UI, Authentication_Client, "Authenticates users via", "OIDC / OAuth2")
Rel(Claim_Submission_UI, Claims_Core_API, "Sends claim data via", "HTTPS / JSON")

@enduml

Integration Worker.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Integration Worker container

Container_Boundary(integration_worker, "Integration Worker") {
    Component(ServiceBusMessageListener, "Service Bus Message Listener", ".NET background service, Azure Service Bus SDK", "Listens for asynchronous events from Azure Service Bus to process background integration tasks.")
    Component(MainframeIntegrationProcessor, "Mainframe Integration Processor", ".NET Core", "Transforms and dispatches integration payloads toward the enterprise integration gateway and legacy systems.")
}

Rel(ServiceBusMessageListener, MainframeIntegrationProcessor, "Forwards received messages for processing")

@enduml

Claim Read Database.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container(Claims Core API, "Claims Core API", ".NET Core", "Modular monolith running in Azure Container Apps")

Container_Boundary(Claim Read Database, "Claim Read Database") {
    Component(Claim Read Store, "Claim Read Store", "Azure SQL Database", "Provides relational read storage with encryption, private endpoints, and Dynamic Data Masking for claims data.")
}

Rel(Claims Core API, Claim Read Store, "Reads and queries claim data", "TDS / TCP")

@enduml
